INSERT INTO article (title, description, created, updated, member_id) VALUES
    ('아침에 먹은 토스트', '식빵을 노릇하게 굽고 딸기잼을 발라 먹었다. 따뜻한 우유와 잘 어울렸다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('학교 가는 길의 고양이', '골목에서 하얀 고양이를 만났다. 잠시 눈을 마주친 뒤 조용히 지나갔다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('새로 산 공책', '표지가 파란 공책을 샀다. 첫 장에 올해 이루고 싶은 일을 적었다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('친구와 한 농구 경기', '운동장에서 친구들과 농구를 했다. 마지막 슛이 들어가서 기분이 좋았다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('비 오는 날의 우산', '하교할 때 비가 내렸다. 친구와 우산을 함께 쓰고 천천히 걸었다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('주말 자전거 타기', '하천 옆 자전거길을 달렸다. 바람이 시원해서 평소보다 멀리 갔다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('도서관에서 고른 책', '모험 이야기가 담긴 책을 빌렸다. 다음 장면이 궁금해 집에서도 계속 읽었다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('오늘의 급식 메뉴', '점심에 카레와 과일이 나왔다. 친구들과 맛있게 먹고 운동장으로 나갔다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('종이비행기 날리기', '종이비행기를 여러 번 접어 보았다. 날개를 조금 바꾸니 더 멀리 날았다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('동네 놀이터 산책', '저녁에 놀이터를 산책했다. 그네를 타고 하늘이 어두워지는 모습을 보았다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('할머니 댁 방문', '할머니 댁에 가서 과일을 먹었다. 옛날이야기를 들으며 즐거운 시간을 보냈다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('첫 번째 화분 가꾸기', '작은 화분에 씨앗을 심었다. 흙이 마르지 않도록 물을 조금씩 주었다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('맛있는 김밥 만들기', '집에서 김밥을 만들었다. 당근과 달걀을 넣고 직접 말아 보았다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('밤하늘의 별 찾기', '베란다에서 별을 찾았다. 구름이 적어서 평소보다 밝게 보였다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('친구 생일 축하', '친구의 생일을 축하했다. 작은 편지를 써서 건네니 친구가 웃었다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('피아노 연습 기록', '어려운 부분을 천천히 연습했다. 어제보다 실수가 줄어 뿌듯했다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('동물원 나들이', '가족과 동물원에 갔다. 기린이 먹이를 먹는 모습이 특히 신기했다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('여름 수박 간식', '더운 오후에 차가운 수박을 먹었다. 달콤한 맛 덕분에 더위가 잊혔다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('축구공을 찾은 날', '운동장 구석으로 굴러간 공을 찾았다. 함께 찾아준 친구에게 고맙다고 말했다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('퍼즐 맞추기 도전', '오백 조각 퍼즐을 시작했다. 가장자리부터 맞추니 모양이 조금씩 보였다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('새 운동화 신고 걷기', '새 운동화를 신고 공원을 걸었다. 발이 편해서 산책이 즐거웠다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('바닷가 모래성', '해변에서 모래성을 만들었다. 파도가 오기 전에 사진을 한 장 찍었다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('초코 쿠키 굽기', '오븐으로 초코 쿠키를 구웠다. 부엌에 달콤한 냄새가 가득했다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('학교 미술 시간', '색연필로 우리 동네 풍경을 그렸다. 나무와 건물을 여러 색으로 칠했다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('버스 창밖 풍경', '버스를 타고 가며 창밖을 구경했다. 노란 은행잎이 길가에 많이 떨어져 있었다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('탁구 첫 승리', '친구와 탁구를 치다가 처음으로 이겼다. 꾸준히 연습한 보람이 있었다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('새로운 보드게임', '친구들과 새로운 보드게임을 했다. 규칙을 익히고 나니 시간이 금방 갔다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('고구마 간식 시간', '따끈한 군고구마를 나누어 먹었다. 손이 따뜻해지고 배도 든든했다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('가을 낙엽 모으기', '공원에서 색이 예쁜 낙엽을 모았다. 책 사이에 넣어 말려 보기로 했다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('동생과 블록 쌓기', '동생과 블록으로 높은 탑을 쌓았다. 무너지지 않게 밑부분을 넓게 만들었다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('산책 중 만난 강아지', '산책하다 귀여운 강아지를 보았다. 주인에게 허락을 받고 살짝 인사했다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('책상 정리한 오후', '책상 위 물건을 정리했다. 필요 없는 종이를 버리니 공간이 넓어졌다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('오늘 배운 과학 실험', '물에 뜨는 물체를 실험했다. 예상과 다른 결과가 나와 더 궁금해졌다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('가족과 영화 감상', '저녁에 가족과 애니메이션을 보았다. 재미있는 장면에서 모두 함께 웃었다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('겨울 목도리 찾기', '옷장에서 작년에 쓰던 목도리를 찾았다. 날씨가 추워지면 다시 사용할 생각이다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('학교 운동회 연습', '운동회에서 할 이어달리기를 연습했다. 바통을 놓치지 않으려고 집중했다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('오랜만에 치킨 먹기', '저녁 메뉴로 치킨을 먹었다. 바삭한 맛이 좋아서 가족과 즐겁게 나눴다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('색종이로 꽃 접기', '색종이로 튤립을 접었다. 여러 색으로 만들어 책상에 세워 두었다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('수족관에서 본 물고기', '수족관에서 파란 물고기 떼를 보았다. 헤엄치는 모습이 아름다웠다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('주말 아침 늦잠', '주말에 알람 없이 늦잠을 잤다. 충분히 쉬고 나니 몸이 가벼웠다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('반 친구들과 청소', '교실을 함께 청소했다. 역할을 나눠 하니 예상보다 빨리 끝났다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('첫 눈사람 만들기', '눈이 쌓여 작은 눈사람을 만들었다. 단추 대신 나뭇잎으로 얼굴을 꾸몄다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('엄마와 시장 구경', '시장에 가서 여러 채소를 구경했다. 저녁에 먹을 귤도 한 봉지 샀다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('아빠와 연날리기', '넓은 공터에서 연을 날렸다. 바람이 불 때마다 연이 높이 올라갔다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('새 학용품 준비', '필통에 연필과 지우개를 넣었다. 준비물을 챙기니 내일이 기대된다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('집에서 만든 레모네이드', '레몬과 얼음을 넣어 음료를 만들었다. 새콤한 맛이 상쾌했다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('작은 발표를 마친 날', '수업 시간에 짧은 발표를 했다. 긴장했지만 끝까지 설명할 수 있었다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('친구에게 배운 마술', '친구가 동전 마술을 알려 주었다. 집에서 연습해 가족에게 보여 줬다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('공원에서 본 무지개', '비가 그친 뒤 하늘에 무지개가 떴다. 잠깐이었지만 선명한 색이 기억난다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1),
    ('방학 계획 세우기', '방학 동안 읽을 책과 하고 싶은 놀이를 적었다. 하루에 하나씩 실천해 볼 생각이다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 1);
INSERT INTO article (title, description, created, updated, member_id) VALUES
    ('출근길 커피 한 잔', '회사 근처 카페에서 따뜻한 아메리카노를 샀다. 커피 향을 맡으며 오늘 일정을 정리했다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('월요일 회의 정리', '팀 회의에서 이번 주 일정을 공유했다. 할 일을 우선순위에 따라 메모했다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('점심시간의 국밥', '동료들과 국밥집에 갔다. 따뜻한 국물을 먹으니 오후 업무를 시작할 힘이 났다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('퇴근 후 동네 산책', '퇴근하고 집 근처를 삼십 분 걸었다. 바람을 쐬니 머리가 한결 맑아졌다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('책상 위 케이블 정리', '뒤엉킨 충전 케이블을 정리했다. 자주 쓰는 선만 남겨 책상이 깔끔해졌다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('주말 장보기 기록', '마트에서 달걀과 채소를 샀다. 미리 적어 간 목록 덕분에 필요한 것만 구매했다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('오랜 친구와 전화', '친구와 오랜만에 통화했다. 학창 시절 이야기를 나누다 보니 시간이 금방 지났다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('자동차 세차한 날', '주말 오전에 세차를 했다. 먼지를 닦고 나니 차가 훨씬 깨끗해 보였다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('저녁으로 만든 된장찌개', '냉장고에 남은 두부와 애호박으로 찌개를 끓였다. 가족들이 맛있게 먹었다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('새로운 업무 도구 배우기', '업무에 도움이 되는 프로그램 사용법을 익혔다. 반복 작업을 줄일 방법이 보였다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('창가 화분에 새 잎', '며칠 전부터 키운 화분에 새 잎이 나왔다. 햇빛이 잘 드는 곳으로 옮겨 주었다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('오후의 짧은 휴식', '일하다 잠시 자리에서 일어나 스트레칭했다. 어깨가 풀려서 다시 집중할 수 있었다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('가족과 주말 드라이브', '교외로 드라이브를 다녀왔다. 창밖의 산과 들을 바라보며 기분을 전환했다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('도서관에서 보낸 두 시간', '도서관에서 관심 있던 경제 책을 읽었다. 기억하고 싶은 문장을 노트에 적었다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('직접 내린 핸드드립 커피', '원두를 갈아 커피를 내려 보았다. 물 붓는 속도에 따라 맛이 달라져 재미있었다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('비 오는 날의 퇴근길', '갑자기 비가 와서 지하철을 이용했다. 창밖으로 떨어지는 빗방울을 바라보았다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('냉장고 식재료 정리', '유통기한이 가까운 재료를 확인했다. 남은 채소로 볶음밥을 만들어 먹었다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('아침 조깅 다시 시작', '오랜만에 운동화를 신고 천천히 뛰었다. 무리하지 않고 꾸준히 하기로 했다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('주말에 본 다큐멘터리', '자연을 주제로 한 다큐멘터리를 봤다. 평소 몰랐던 동물의 습성이 흥미로웠다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('동료의 작은 축하', '프로젝트를 마친 동료에게 축하 메시지를 보냈다. 서로 격려하니 팀 분위기가 좋았다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('새로 바꾼 키보드', '오래 쓰던 키보드를 교체했다. 키감이 편해져 문서 작성이 즐거워졌다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('베란다 청소하기', '베란다에 쌓인 먼지를 쓸고 물걸레질했다. 환기를 하니 집 안 공기도 상쾌해졌다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('가을 산책길 사진', '공원에서 단풍 사진을 찍었다. 햇빛을 받은 나뭇잎 색이 특히 아름다웠다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('집 근처 빵집 발견', '새로 생긴 빵집에서 소금빵을 샀다. 다음에는 다른 빵도 먹어 보고 싶다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('일정 관리 방법 바꾸기', '달력에 중요한 약속과 할 일을 구분해서 적었다. 한눈에 확인할 수 있어 편리했다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
    ('출장 준비 체크리스트', '내일 필요한 자료와 충전기를 가방에 넣었다. 미리 챙기니 마음이 편해졌다.', CURRENT_TIMESTAMP(6), CURRENT_TIMESTAMP(6), 2),
